                        "PyYAML is required to parse .yaml files"
                    )
                return yaml.safe_load(f)
            return json.load(f)
    except (json.JSONDecodeError, yaml.YAMLError) if yaml else Exception as exc:
        raise HarnessError(f"Failed to parse config {config_path}: {exc}") from exc

